# Initialize Chat

`v0-auto` is deprecated. Requests using it are handled as `v0-pro`. Use `v0-pro` for new integrations.

## Usage

<CodeVariant
language="TypeScript"
title="TypeScript Example"
code={`import  from 'v0-sdk'

const result = await v0.chats.init({
type: 'files',
files: [
{
name: 'app/globals.css',
content: "body "
},
],
})

console.log(result)`}
/>

<CodeVariant
language="cURL"
title="cURL Example"
code={`curl -X POST "https://api.v0.dev/v1/chats/init" \
-H "Authorization: Bearer $V0_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"type": "files",
"files": [
{
"name": "app/globals.css",
"content": "body "
}
]
}'`}
/>

<CodeVariant
language="TypeScript"
title="TypeScript Example"
code={`import  from 'v0-sdk'

const result = await v0.chats.init({
type: 'repo',
repo: {
url: 'https://github.com/vercel/next.js',
branch: 'canary',
},
name: 'Analyze Next.js repo',
})

console.log(result)`}
/>

<CodeVariant
language="cURL"
title="cURL Example"
code={`curl -X POST "https://api.v0.dev/v1/chats/init" \
-H "Authorization: Bearer $V0_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"type": "repo",
"repo": {
"url": "https://github.com/vercel/next.js",
"branch": "canary"
},
"name": "Analyze Next.js repo"
}'`}
/>

<CodeVariant
language="TypeScript"
title="TypeScript Example"
code={`import  from 'v0-sdk'

const result = await v0.chats.init({
type: 'registry',
registry: {
url: 'https://ui.shadcn.com/registry/blocks/dashboard-01.json',
},
name: 'Customize dashboard component',
})

console.log(result)`}
/>

<CodeVariant
language="cURL"
title="cURL Example"
code={`curl -X POST "https://api.v0.dev/v1/chats/init" \
-H "Authorization: Bearer $V0_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"type": "registry",
"registry": {
