"name": "Customize dashboard component"
}'`}
/>

<CodeVariant
language="TypeScript"
title="TypeScript Example"
code={`import  from 'v0-sdk'

const result = await v0.chats.init({
type: 'zip',
zip: {
url: 'https://example.com/starter-template.zip',
},
lockAllFiles: true,
name: 'Modify starter template',
})

console.log(result)`}
/>

<CodeVariant
language="cURL"
title="cURL Example"
code={`curl -X POST "https://api.v0.dev/v1/chats/init" \
-H "Authorization: Bearer $V0_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"type": "zip",
"zip": {
"url": "https://example.com/starter-template.zip"
},
"lockAllFiles": true,
"name": "Modify starter template"
}'`}
/>

<CodeVariant
language="TypeScript"
title="TypeScript Example"
code={`import  from 'v0-sdk'

const result = await v0.chats.init({
type: 'files',
files: [
{
name: 'app/page.tsx',
content: 'export default function Page() '
},
],
metadata: {
userId: 'user_abc123',
organizationId: 'org_xyz789',
source: 'mobile-app',
},
})

// Later, retrieve the metadata
console.log(result.metadata.userId) // 'user_abc123'`}
/>

<CodeVariant
language="cURL"
title="cURL Example"
code={`curl -X POST "https://api.v0.dev/v1/chats/init" \
-H "Authorization: Bearer $V0_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"type": "files",
"files": [
{
"name": "app/page.tsx",
"content": "export default function Page() "
}
],
"metadata": {
"userId": "user_abc123",
"organizationId": "org_xyz789",
"source": "mobile-app"
}
}'`}
/>

